head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF30625.xml"; //교육참가현황 등록
scwin.gLastJob = "";

//자료수정 시 부모창으로부터 넘어온 데이터
scwin.key_edu_partc_id = frame.opener.scwin.key_edu_partc_id; //PK
scwin.key_isur_cd = frame.opener.scwin.key_isur_cd; //회사코드
scwin.key_com_abbrv = frame.opener.scwin.key_com_abbrv; //회사명
scwin.key_chrg_tp_cd = frame.opener.scwin.key_chrg_tp_cd; //담당자구분코드
scwin.key_edu_id = frame.opener.scwin.key_edu_id; //교육일정코드
scwin.key_chrg_nm = frame.opener.scwin.key_chrg_nm; // 선택된참가자명
scwin.key_edu_nm = frame.opener.scwin.key_edu_nm; // 선택과정명
scwin.key_edu_ack_tm = frame.opener.scwin.key_edu_ack_tm;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 이수시간


// 대상년도 초기화
scwin.fn_Init = function() {
    /*
    	var ToDay = new Date();
    	var yyyy = parseInt(ToDay.getYear(), 10);
    	var str = "^전체";
    	for (var i = yyyy; i >= 2010 ; i--)
    	{
    		str += "," + i + "%^" + i;
    	}
    	//alert(str);
    	cmb_YYYY.CBData = str;
    */

    dts_year.DataID = encodeURI("/ListedCompany.do?method=selectMinMaxYear&outputMessageId=DISCLS_MIN_MAX_YEAR_OUT");
    dts_year.Reset();
};
scwin.fn_setYear = function() {
    dts_year.DataID = encodeURI("/ListedCompany.do?method=selectMinMaxYear&outputMessageId=DISCLS_MIN_MAX_YEAR_OUT");
    dts_year.Reset();
    var minYear = dts_year.getCellData(1, "MIN_YEAR");
    var maxYear = dts_year.getCellData(1, "MAX_YEAR");
    var str = "^전체";
    for (var i = maxYear; i >= minYear; i--) {
        str += "," + i + "%^" + i;
    }
    //alert(str);
    cmb_YYYY.CBData = str;

    //default 현재년도 
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    $c.stf.setObjectValue(cmb_YYYY, yyyy + "%");
};




// 담당자구분 초기화(최초)
scwin.fn_setChrgTpCd = function() {
    cmb_EDU_KIND_CD.ClearData();
    cmb_EDU_KIND_CD.CBData = "^전체,11^공시책임자교육,12^공시담당자(정)교육,13^공시담당자(부)교육,14^공시대리인교육,15^공시담당보조자교육";
};


// 담당자구분 초기화(최초 이후, 교육참가자 선택 시)
scwin.fn_setChrgTpCd2 = function(chrg_tp_cd) {
    cmb_EDU_KIND_CD.ClearData();
    var str = "";
    if (chrg_tp_cd == "11") {
        str = "11^공시책임자교육";
    } else {
        str = "12^공시담당자(정)교육,13^공시담당자(부)교육,14^공시대리인교육,15^공시담당보조자교육";
    }
    cmb_EDU_KIND_CD.CBData = str;
};


// 수정일 경우 기존 값 셋팅
scwin.fn_Init_modify = function() {
    //수정일 경우에만 실행
    if (scwin.key_edu_partc_id != "") {
        // 1. 수정자 정보 화면표시 셋팅
        txb_selectedNm.setValue(scwin.key_chrg_nm);
        tbx_hdn_isur_cd.setValue(scwin.key_isur_cd);
        tbx_hdn_chrg_tp_cd.setValue(scwin.key_chrg_tp_cd);
        txb_selectedEduNm.setValue(scwin.key_edu_nm);
        txb_selectedEduAckTm.setValue(scwin.key_edu_ack_tm);
        tbx_hdn_edu_id.setValue(scwin.key_edu_id);

        // 2. 교육참가자 그리드 셋팅
        txb_isur_cd.setValue(scwin.key_isur_cd);
        txb_com_abbrv.setValue(scwin.key_com_abbrv);
        txb_chrg_nm.setValue(scwin.key_chrg_nm);
        scwin.fn_Search();
        scwin.fn_Search2(tbx_hdn_edu_id.getValue());

        // 3. 담당자구분 콤보박스 셋팅
        scwin.fn_setChrgTpCd2(scwin.key_chrg_tp_cd);
    }
};



//담당자 검색
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompany.do?method=listDisclsEduNattend";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    url += "&EDU_KIND_CD=";
    url += "&YYYY=";
    url += "&EMP_NO=";
    url += "&DEP_CD=";
    url += "&CHRG_NM=" + $c.stf.getObjectValue(txb_chrg_nm);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_ComDisclsPerson.DataID = encodeURI(url);
    dts_ComDisclsPerson.Reset();
};



//교육 검색(파라미터가 있을경우, 해당 ID로 조회)
scwin.fn_Search2 = function(edu_schdl_id) {
    if (txb_selectedNm.getValue() == '') {
        $c.win.alert("교육참가자 선택 후 조회 가능합니다.");
        return;
    }
    $c.cm.ShowWin(grd_Grid2);
    var url = "/ListedCompany.do?method=listDisclsEduSchdl";
    url += "&EDU_KIND_CD=" + $c.stf.getObjectValue(cmb_EDU_KIND_CD);
    url += "&OBJ_YY=" + $c.stf.getObjectValue(cmb_YYYY);
    if (edu_schdl_id != null) {
        //조회버튼 클릭 시 PK값의 할당을 방지하기 위해 IF문 사용
        url += "&EDU_SCHDL_ID=" + edu_schdl_id;
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Edu_Plan.DataID = encodeURI(url);
    dts_Edu_Plan.Reset();
};



//저장
scwin.fn_Save = function() {
    if (txb_selectedNm.getValue() == '') {
        $c.win.alert('교육참가자를 선택하시기 바랍니다.');
        return;
    }
    if (txb_selectedEduNm.getValue() == '') {
        $c.win.alert('교육과정을 선택하시기 바랍니다.');
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        var url = "/ListedCompany.do?method=saveDisclsEduPartc";
        url += "&EDU_PARTC_ID=" + scwin.key_edu_partc_id;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};
scwin.fn_setHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ISSUEINFO_DISCLS_EDU_PARTC_INOUT";
    dts_Save.Reset();
    dts_Save.insertRow();
};


//삭제 버튼 클릭 시
scwin.fn_Delete = function() {
    if (window.confirm("[삭제]하시겠습니까?")) {
        scwin.gLastJob = "삭제";
        var url = "/ListedCompany.do?method=deleteDisclsEduPartc";
        url += "&EDU_PARTC_ID=" + scwin.key_edu_partc_id;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.post();
    }
};
scwin.dts_ComDisclsPerson_OnFail = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadError = function() {
    $c.stf.alert_error(dts_ComDisclsPerson);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_ComDisclsPerson_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_ComDisclsPerson.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.grd_Grid_OnClick = function(row, colid) {
    var CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); //담당자명
    var EDU_KIND_NM = dts_ComDisclsPerson.getCellData(row, "EDU_KIND_NM"); //교육구분
    var ISUR_CD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); //회사코드
    var CHRG_TP_CD = dts_ComDisclsPerson.getCellData(row, "CHRG_TP_CD"); //회사코드

    txb_selectedNm.setValue(CHAR_NM); //+ " [" + EDU_KIND_NM + "]" ;
    tbx_hdn_isur_cd.setValue(ISUR_CD);
    tbx_hdn_chrg_tp_cd.setValue(CHRG_TP_CD);


    //선택한 교육참가자의 담당자구분코드를 취득하여 콤보박스의 값을 설정
    scwin.fn_setChrgTpCd2(tbx_hdn_chrg_tp_cd.getValue()); //콤보 초기화
    scwin.fn_Search2(); // 교육과정 조회

};
scwin.grd_Grid_OnDblClick = function(row, colid) {

};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_chrg_nm_onkeypress = function() {
    scwin.fn_Search(); //엔터키 입력시 조회 수행

};
scwin.btn_Search2_onclick = function() {
    scwin.fn_Search2();
};
scwin.dts_Edu_Plan_OnFail = function() {
    $c.stf.alert_error(dts_Edu_Plan);
    $c.cm.CloseWin('', grd_Grid2);
};
scwin.dts_Edu_Plan_OnLoadError = function() {
    $c.stf.alert_error(dts_Edu_Plan);
    $c.cm.CloseWin('', grd_Grid2);
};
scwin.dts_Edu_Plan_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_Edu_Plan.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid2); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid2_OnClick = function(row, colid) {
    var EDU_NM = dts_Edu_Plan.getCellData(row, "DISCLS_EDU_CRS_NM"); //과정명
    var EDU_ACK_TM = dts_Edu_Plan.getCellData(row, "EDU_ACK_TM"); //이수시간
    var EDU_SCHDL_ID = dts_Edu_Plan.getCellData(row, "EDU_SCHDL_ID"); //교육ID

    txb_selectedEduNm.setValue(EDU_NM);
    txb_selectedEduAckTm.setValue(EDU_ACK_TM + ' 시간');
    tbx_hdn_edu_id.setValue(EDU_SCHDL_ID);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("Error Code : " + trs_Save.ErrorCode + "\n" + "Error Message : " + trs_Save.ErrorMsg + "\n");
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_Search;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Init();
    scwin.fn_setYear();
    scwin.fn_setHeader();
    scwin.fn_setChrgTpCd();
    scwin.fn_Init_modify();

    //입력모드일때 '삭제'버튼 숨김
    if (scwin.key_edu_partc_id != "") {
        $c.stf.showObj(btn_Delete, true);
    } else {
        $c.stf.showObj(btn_Delete, false);
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
